/**
 * The vocabularies the pinned XSDs declare, one per namespace, 11 rosters of 634 kinds, and the 317
 * kinds a schema declares globally.
 *
 * Generated by `node src/vocab/derive/declarations.ts vocabularies` and formatted with `vp fmt`;
 * `src/vocab/derive/declarations.test.ts` checks that a re-run reproduces this file byte for byte.
 * A roster lists its kinds in the order its XSDs first declare them, the 3.0 XSDs' first, which is
 * their append-only code order.
 */
import type { SchemaVersion } from "#pantry/grammar/kinds.ts";
import type { GlobalKind, RosterKind, VocabularyRoster } from "#pantry/vocab/inventory/types.ts";

/**
 * Both schema versions.
 */
const everyVersion = ["3.0.0", "3.0.1"] as const;

/**
 * One kind of a roster.
 *
 * @param handle - Its handle.
 * @param local - Its element's local name.
 * @returns The kind.
 */
const kind = <const Handle extends string>(
  handle: Handle,
  local: string,
): RosterKind & { readonly handle: Handle } => ({ handle, local });

/**
 * One kind declared globally.
 *
 * @param handle - The kind.
 * @param versions - The versions it is declared in.
 * @returns The row.
 */
const global = (
  handle: string,
  versions: readonly [SchemaVersion, ...SchemaVersion[]],
): GlobalKind => ({ kind: handle, versions });

